/**
 * 无极（wuji）场景配置 API 地址集中管理。
 *
 * 消除 route-params.ts / entry-prerender.ts 中重复硬编码的 wuji 场景配置 URL，
 * 统一维护 appid / schemaid / schemakey 等参数，避免多处修改遗漏。
 *
 * @changelog
 * | 版本   | 变更说明                                                 | 关联                  |
 * | v1.0.0 | 初始实现：集中场景配置 API 常量，消除多文件 URL 重复      | REQ: 消除重复 URL     |
 * /@changelog
 *
 * @author v_djlzhou
 */

/** 无极 API 主机（生产环境） */
export const WUJI_API_HOST = 'https://api.wuji.qq.com';

/** 无极 API 路径前缀 */
export const WUJI_API_PATH_PREFIX = '/x/api';

/** 场景配置接口 query 参数（appid + schemaid + schemakey） */
export const WUJI_SCENE_CONFIG_QUERY =
  'appid=my_buddy_test&schemaid=scene_pos_config_v2&schemakey=31bfc3054bb54a299ccf2c06a33162d9';

/** 场景配置接口资源路径（含 query，不含 host） */
export const WUJI_SCENE_CONFIG_PATH = `/wuji_cache/object?${WUJI_SCENE_CONFIG_QUERY}`;

/** 场景配置接口完整 URL（生产环境，供预渲染等仅需生产地址的场景使用） */
export const WUJI_SCENE_CONFIG_URL = `${WUJI_API_HOST}${WUJI_API_PATH_PREFIX}${WUJI_SCENE_CONFIG_PATH}`;

/** 本地开发代理前缀（Vite proxy，见 vite.config.js） */
export const WUJI_API_DEV_PROXY = '/api_wuji';
